<template><VCard title="Expediente KYC"><VCardText v-if="item"><p><strong>Usuario:</strong> {{ item.user?.name }}</p><p><strong>Estado:</strong> {{ statusLabel(item.workflow_status) }} ({{ statusLabel(item.status) }})</p><p><strong>Nivel:</strong> {{ item.level }} · Nivel 3 {{ hasLevelThree ? "activo" : "inactivo" }}</p><p><strong>Tipo de documento:</strong> {{ item.type_document_name ?? item.type_documents_id }}</p><p><strong>Documento:</strong> {{ item.document_masked }}</p><p><strong>Pais:</strong> {{ item.country_name ?? item.country_id }}</p><pre class="safe-details">{{ item.personal_data }}</pre><VBtn v-for="document in item.documents" :key="document.public_reference ?? document.download_endpoint" class="mr-2" variant="outlined" @click="api.downloadDocument(document)">{{ document.document_type }} · {{ statusLabel(document.status) }}</VBtn><template v-if="item.workflow_status === 'approved'"><VTextarea v-model="reason" class="mt-4" label="Motivo para Nivel 3" /><VBtn :disabled="reason.trim().length < 3" @click="setLevelThree">{{ hasLevelThree ? "Revocar Nivel 3" : "Aprobar Nivel 3" }}</VBtn></template></VCardText></VCard></template>
<script setup lang="ts">
import { useTwoFactorGuard } from "@/composables/useTwoFactorGuard";

const { authorizeWithTwoFactor } = useTwoFactorGuard();
import { statusLabel } from "@/utils/statusLabels"; import { useKycApi } from "@/services/kycApi"; import { computed, onMounted, ref } from "vue"; import { useRoute } from "vue-router"; const route = useRoute(); const api = useKycApi(); const item = ref<any>(null); const reason = ref(""); const hasLevelThree = computed(() => Boolean(item.value?.advanced_level_approved_at)); const load = async () => { item.value = await api.show(Number(route.params.id)); }; const setLevelThree = async () => { if (!item.value || item.value.workflow_status !== "approved" || reason.value.trim().length < 3) return; await authorizeWithTwoFactor(api.levelThree.bind(api, item.value.id, !hasLevelThree.value, reason.value.trim()), "admin.security"); reason.value = ""; await load(); }; onMounted(load);</script><style scoped>.safe-details { white-space: pre-wrap; }</style>
